window.LIB_LAZY=window.LIB_LAZY||{};
window.LIB_LAZY["eusebiu-istoria#80"]=[{"v":1,"t":"Pe la al doisprezecelea an al domniei lui Traian, pomenitul episcop al parohiei Alexandriei a murit și Primus, al patrulea în șir de la apostoli, a fost ales la slujbă."},{"v":2,"t":"În acel timp, Alexandru, al cincilea în șirul de succesiune de la Petru și Pavel, a primit episcopatul la Roma, după ce Evarist ținuse slujba opt ani."}];
window.LIB_LAZY["eusebiu-istoria#81"]=[{"v":1,"t":"Învățătura și Biserica Mântuitorului nostru înfloreau mult și înaintau de la o zi la alta; dar nenorocirile iudeilor sporeau și ei îndurau o neîntreruptă urmare de rele. În al optsprezecelea an al domniei lui Traian a mai fost o tulburare a iudeilor, prin care a pierit o mare mulțime dintre ei."},{"v":2,"t":"Căci în Alexandria și în restul Egiptului și, de asemenea, în Cirene, ca și cum ar fi fost stârniți de un duh cumplit și răzvrătitor, s-au năpustit în măsuri de răscoală împotriva concetățenilor lor, grecii. Răscoala a crescut mult și, în anul următor, pe când Lupus era guvernatorul întregului Egipt, a ajuns un război de nu mică mărime."},{"v":3,"t":"În prima ciocnire s-a întâmplat că au biruit pe greci, care au fugit la Alexandria și au închis și au omorât pe iudeii care erau în cetate. Dar iudeii din Cirene, deși lipsiți de ajutorul lor, au continuat să jefuiască țara Egiptului și să pustiască ținuturile ei, sub conducerea lui Lucua. Împotriva lor împăratul a trimis pe Marciu Turbo cu o forță de pedestrași și de corăbii și, de asemenea, cu o forță de călărime."},{"v":4,"t":"El a purtat războiul împotriva lor multă vreme și a dat multe bătălii și a omorât multe mii de iudei, nu numai dintre cei din Cirene, ci și dintre cei care locuiau în Egipt și veniseră în ajutorul regelui lor Lucua."},{"v":5,"t":"Dar împăratul, temându-se că iudeii din Mesopotamia vor face și ei un atac asupra locuitorilor acelei țări, i-a poruncit lui Lucius Quintus să curețe provincia de ei. Și el, mărșăluind împotriva lor, a omorât o mare mulțime dintre cei care locuiau acolo; și în urma izbânzii lui a fost făcut de împărat guvernator al Iudeii. Aceste întâmplări sunt însemnate chiar în aceste cuvinte și de istoricii greci care au scris povestiri despre acele vremuri."}];
window.LIB_LAZY["eusebiu-istoria#82"]=[{"v":1,"t":"După ce Traian domnise nouăsprezece ani și jumătate, Aelius Adrian i-a urmat la imperiu. Lui i-a adresat Cuadrat o cuvântare care cuprinde o apologie pentru religia noastră, pentru că unii oameni răi încercaseră să tulbure pe creștini. Lucrarea este încă în mâinile multora dintre frați, ca și în ale noastre, și dă dovezi limpezi ale priceperii omului și ale ortodoxiei lui apostolice."},{"v":2,"t":"El însuși arată vremea timpurie în care a trăit în cuvintele următoare: „Dar lucrările Mântuitorului nostru erau totdeauna de față, căci erau adevărate:— cei care fuseseră vindecați și cei care fuseseră înviați din morți, care au fost văzuți nu numai când au fost vindecați și când au fost înviați, ci au fost și totdeauna de față; și nu numai cât timp Mântuitorul era pe pământ, ci și după moartea Lui au fost vii destul timp, așa încât unii dintre ei au trăit chiar până în ziua noastră.” Astfel era, deci, Cuadrat."},{"v":3,"t":"Aristid, de asemenea, un credincios închinat cu înfocare religiei noastre, a lăsat, ca și Cuadrat, o apologie pentru credință, adresată lui Adrian. Lucrarea lui a fost păstrată și ea până în ziua de azi de foarte multe persoane."}];
window.LIB_LAZY["eusebiu-istoria#83"]=[{"v":1,"t":"În al treilea an al aceleiași domnii, Alexandru, episcopul Romei, a murit după ce ținuse slujba zece ani. Urmaș i-a fost Xist. Cam în același timp, Primus, episcopul Alexandriei, a murit în al doisprezecelea an al episcopatului lui și i-a urmat Iust."}];
window.LIB_LAZY["eusebiu-istoria#84"]=[{"v":1,"t":"Cronologia episcopilor Ierusalimului nu am găsit-o păstrată în scris nicăieri; căci tradiția spune că toți au trăit puțin."},{"v":2,"t":"Dar atât am aflat din scrieri, că până la asediul iudeilor care a avut loc sub Adrian au fost acolo cincisprezece episcopi, în șir, dintre care toți se spune că au fost de neam evreu și au primit cunoașterea lui Hristos în curăție, așa încât au fost încuviințați de cei în stare să judece asemenea lucruri și au fost socotiți vrednici de episcopat. Căci toată biserica lor se alcătuia atunci din evrei credincioși care au continuat din zilele apostolilor până la asediul care a avut loc în acest timp; în care asediu iudeii, răsculându-se din nou împotriva romanilor, au fost biruiți după aspre bătălii."},{"v":3,"t":"Dar de vreme ce episcopii din tăierea împrejur au încetat în acest timp, este cuvenit să dăm aici o listă a numelor lor de la început. Cel dintâi, deci, a fost Iacov, așa-numitul frate al Domnului; al doilea, Simeon; al treilea, Iust; al patrulea, Zaheu; al cincilea, Tobia; al șaselea, Beniamin; al șaptelea, Ioan; al optulea, Matia; al nouălea, Filip; al zecelea, Seneca; al unsprezecelea, Iust; al doisprezecelea, Levi; al treisprezecelea, Efres; al paisprezecelea, Iosif; și, în sfârșit, al cincisprezecelea, Iuda."},{"v":4,"t":"Aceștia sunt episcopii Ierusalimului care au trăit între vremea apostolilor și vremea pomenită, toți aparținând tăierii împrejur."},{"v":5,"t":"În al doisprezecelea an al domniei lui Adrian, Xist, după ce împlinise al zecelea an al episcopatului lui, a fost urmat de Telesfor, al șaptelea în succesiune de la apostoli. Între timp, după trecerea unui an și a câtorva luni, Eumene, al șaselea în ordine, a urmat la conducerea bisericii alexandrine, înaintașul lui ținând slujba unsprezece ani."}];
window.LIB_LAZY["eusebiu-istoria#85"]=[{"v":1,"t":"Pe măsură ce răscoala iudeilor din acest timp a devenit mult mai serioasă, Ruf, guvernatorul Iudeii, după ce împăratul îi trimisese o forță de ajutor, folosind nebunia lor ca pretext, a înaintat împotriva lor fără milă și a nimicit fără deosebire mii de bărbați, femei și copii și, potrivit legilor războiului, a adus țara lor într-o stare de deplină supunere."},{"v":2,"t":"Conducătorul iudeilor în acest timp era un om cu numele Barcohba (care înseamnă o stea), care avea caracterul unui tâlhar și al unui ucigaș, dar totuși, bizuindu-se pe numele lui, se lăuda înaintea lor, ca înaintea unor robi, că stăpânește puteri minunate; și se preface că este o stea care coborâse la ei din cer ca să le aducă lumină în mijlocul nenorocirilor lor."},{"v":3,"t":"Războiul s-a înfuriat cel mai aprig în al optsprezecelea an al lui Adrian, la cetatea Betar, care era o fortăreață foarte sigură, așezată nu departe de Ierusalim. După ce asediul ținuse mult timp și răsculații fuseseră aduși la ultima strâmtorare de foame și de sete și instigatorul răscoalei îndurase pedeapsa lui dreaptă, tot neamul a fost oprit din acest timp, printr-un decret și prin poruncile lui Adrian, de a mai urca vreodată în țara din jurul Ierusalimului. Căci împăratul a dat poruncă să nu vadă nici măcar de departe țara părinților lor. Aceasta este povestirea lui Aristo din Pella."},{"v":4,"t":"Și astfel, când cetatea a fost golită de neamul iudeu și a suferit nimicirea totală a vechilor ei locuitori, a fost colonizată de un alt neam, iar cetatea romană care s-a ridicat după aceea și-a schimbat numele și a fost numită Elia, în cinstea împăratului Aelius Adrian. Și cum biserica de acolo era acum alcătuită din neamuri, primul care a luat cârmuirea ei după episcopii din tăierea împrejur a fost Marcu."}];
window.LIB_LAZY["eusebiu-istoria#86"]=[{"v":1,"t":"Pe măsură ce bisericile din toată lumea străluceau acum ca cele mai strălucitoare stele și credința în Mântuitorul și Domnul nostru Isus Hristos înflorea între tot neamul omenesc, demonul care urăște tot ce este bun și este totdeauna dușman adevărului și cel mai amarnic potrivnic mântuirii omului și-a întors toate meșteșugurile împotriva Bisericii. La început s-a înarmat împotriva ei cu prigoane din afară."},{"v":2,"t":"Dar acum, fiind oprit de la folosirea unor asemenea mijloace, a născocit tot felul de planuri și a folosit alte metode în lupta lui cu Biserica, slujindu-se de oameni josnici și înșelători ca unelte pentru pieirea sufletelor și ca slujitori ai nimicirii. Îndemnați de el, înșelători și amăgitori, luând numele religiei noastre, au adus la adâncul pierzării pe cei dintre credincioși pe care i-au putut câștiga și, în același timp, prin faptele pe care le practicau, au abătut de la calea care duce la cuvântul mântuirii pe cei neștiutori ai credinței."},{"v":3,"t":"De aceea a ieșit din acel Menandru, pe care l-am pomenit deja ca urmaș al lui Simon, o anumită putere șerpească, cu două limbi și două capete, care a născut pe conducătorii a două erezii deosebite, Saturnin, antiohian de neam, și Basilide, alexandrin. Cel dintâi a întemeiat școli de erezie fără Dumnezeu în Siria, cel de-al doilea în Alexandria."},{"v":4,"t":"Irineu spune că învățătura mincinoasă a lui Saturnin se învoia în cele mai multe privințe cu cea a lui Menandru, dar că Basilide, sub pretextul unor taine de nespus, a născocit povești monstruoase și a dus născocirile ereziei lui nelegiuite cu totul peste margini."},{"v":5,"t":"Dar după cum erau în acel timp foarte mulți membri ai Bisericii care luptau pentru adevăr și apărau învățătura apostolică și bisericească cu o elocvență neobișnuită, tot așa au fost și unii care au dat urmașilor, prin scrierile lor, mijloace de apărare împotriva ereziilor la care ne-am referit."},{"v":6,"t":"Dintre aceștia a ajuns până la noi o foarte puternică combatere a lui Basilide de către Agrippa Castor, unul dintre cei mai vestiți scriitori ai acelei vremi, care arată cumplita înșelăciune a omului."},{"v":7,"t":"Dezvăluindu-i tainele, spune că Basilide a scris douăzeci și patru de cărți despre Evanghelie și că și-a născocit proroci numiți Barcaba și Barcof și alții care nu au existat și că le-a dat nume barbare ca să uimească pe cei care se minunează de asemenea lucruri; că a învățat și că mâncatul cărnii jertfite idolilor și lepădarea fără păzire a credinței în vremuri de prigoană sunt lucruri nepăsătoare; și că a poruncit urmașilor lui, ca Pitagora, o tăcere de cinci ani."},{"v":8,"t":"Alte lucruri asemănătoare a însemnat pomenitul scriitor despre Basilide și a dezvăluit cu iscusință rătăcirea ereziei lui."},{"v":9,"t":"Irineu scrie și că Carpocrate a fost contemporan cu acești oameni și că a fost tatăl unei alte erezii, numită erezia gnosticilor, care nu voiau să mai transmită meșteșugurile magice ale lui Simon, cum făcuse acela, în taină, ci pe față. Căci se lăudau — ca de ceva mare — cu băuturi de dragoste pregătite cu grijă de ei și cu anumiți demoni care le trimiteau vise și le dădeau ocrotirea lor și cu alte asemenea mijloace; și potrivit cu aceste lucruri învățau că este necesar ca cei care voiau să intre deplin în tainele lor, sau mai bine zis în urâciunile lor, să practice toate cele mai rele feluri de răutate, pe motiv că nu puteau scăpa de puterile cosmice, cum le numeau, în niciun alt chip decât îndeplinindu-și îndatoririle față de ele toate prin purtare rușinoasă."},{"v":10,"t":"Astfel s-a întâmplat că demonul cel rău, slujindu-se de acești slujitori, pe de o parte i-a înrobit pe cei care erau atât de jalnic rătăciți de ei spre propria lor nimicire, iar pe de altă parte a dat păgânilor necredincioși prilejuri îndestulătoare de a clevetări cuvântul dumnezeiesc, întrucât faima acestor oameni aducea rușine asupra întregului neam al creștinilor."},{"v":11,"t":"În acest chip s-a întâmplat, deci, că s-a răspândit despre noi între necredincioșii acelei epoci bănuiala rușinoasă și cât se poate de absurdă că am avea legături nepermise cu mame și surori și că ne-am desfăta cu ospețe nelegiuite."},{"v":12,"t":"El nu a izbutit, totuși, mult timp în aceste meșteșuguri, pentru că adevărul s-a întemeiat și în timp a strălucit cu mare strălucire."},{"v":13,"t":"Căci uneltirile dușmanilor ei au fost combătute de puterea ei și au dispărut repede. Câte o erezie nouă s-a ridicat după alta și cele dinainte au trecut totdeauna și, acum într-un timp, acum în altul, acum într-un fel, acum în alte feluri, s-au pierdut în idei de felurite soiuri și forme. Dar strălucirea Bisericii catolice și singura adevărată, care este totdeauna aceeași, a crescut în mărime și putere și și-a răsfrânt evlavia și simplitatea și libertatea și modestia și curăția vieții și filozofiei ei insuflate către fiecare neam, atât de greci, cât și de barbari."},{"v":14,"t":"În același timp au dispărut și învinuirile clevetitoare care fuseseră aduse întregii Biserici și a rămas numai învățătura noastră, care a biruit peste toate și care este recunoscută ca superioară tuturor în demnitate și cumpătare și în doctrinele dumnezeiești și filozofice. Așa încât niciunul dintre ei nu mai cutează acum să lipească credinței noastre o clevetire josnică sau vreo asemenea ocară cum le plăcea dușmanilor noștri din vechime să rostească."},{"v":15,"t":"Totuși, în acele vremuri, adevărul a chemat din nou la arme mulți campioni care s-au luptat în apărarea lui împotriva ereziilor fără Dumnezeu, combătându-le nu numai cu argumente rostite, ci și cu scrise."}];
window.LIB_LAZY["eusebiu-istoria#87"]=[{"v":1,"t":"Printre aceștia Hegesip era bine cunoscut. Am citat deja cuvintele lui de mai multe ori, povestind întâmplări care au avut loc în vremea apostolilor după relatarea lui."},{"v":2,"t":"El însemnează în cinci cărți adevărata tradiție a învățăturii apostolice într-un stil foarte simplu și arată vremea în care a înflorit când scrie astfel despre cei care au ridicat întâi idoli: „Cărora le-au ridicat cenotafuri și temple, cum se face până în ziua de azi. Printre care este și Antinou, un rob al împăratului Adrian, în cinstea căruia se celebrează și jocurile antinoiene, care au fost înființate în vremea noastră. Căci a întemeiat și o cetate numită după Antinou și a rânduit proroci.”"},{"v":3,"t":"În același timp și Iustin, un adevărat iubitor al filozofiei adevărate, continua încă să se îndeletnicească cu literatura greacă. El arată această vreme în Apologia pe care a adresat-o lui Antonin, unde scrie astfel: „Nu socotim nepotrivit să pomenim aici și pe Antinou, care a trăit în vremea noastră și căruia toți au fost mânați de frică să i se închine ca unui dumnezeu, deși știau cine era și de unde venea.”"},{"v":4,"t":"Același scriitor, vorbind despre războiul iudeilor care a avut loc în acel timp, adaugă următoarele: „Căci în recentul război al iudeilor, Barcohba, conducătorul răscoalei iudeilor, a poruncit ca numai creștinii să fie pedepsiți cu pedepse cumplite dacă nu se vor lepăda și nu vor huli pe Isus Hristos.”"},{"v":5,"t":"Și în aceeași lucrare arată că trecerea lui de la filozofia greacă la creștinism nu a fost fără temei, ci a fost rezultatul unei chibzuiri din partea lui. Cuvintele lui sunt următoarele: „Căci eu însumi, pe când mă desfătam cu învățăturile lui Platon și auzeam pe creștini clevetiți și vedeam că nu se temeau nici de moarte, nici de nimic altceva privit de obicei ca cumplit, am ajuns la încheierea că este cu neputință ca ei să trăiască în răutate și plăcere. Căci ce om iubitor de plăceri sau neînfrânat, sau ce om care socotește bine să se ospăteze cu carne omenească, ar putea primi cu bucurie moartea ca să fie lipsit de desfătările lui și nu s-ar sili mai degrabă să-și continue viața de acum și să scape de luarea-aminte a cârmuitorilor, în loc să se dea să fie dat la moarte?”"},{"v":6,"t":"Același scriitor, pe lângă aceasta, povestește că Adrian, primind de la Serenius Granian, un guvernator foarte distins, o scrisoare în folosul creștinilor, în care arăta că nu este drept să se omoare creștinii fără o învinuire și o judecată regulată, numai ca să se satisfacă strigătele poporului, a trimis un rescript lui Minuciu Fundan, proconsul al Asiei, poruncindu-i să nu osândească pe nimeni fără o învinuire și o acuzație bine întemeiată."},{"v":7,"t":"Și dă o copie a epistolei, păstrând latina originală în care a fost scrisă și punând înainte următoarele cuvinte: „Deși din epistola preamarelui și preaslăvitului împărat Adrian, tatăl tău, avem un bun temei să cerem să porunciți să se dea judecată după cum am dorit, totuși am cerut aceasta nu pentru că a fost poruncită de Adrian, ci mai degrabă pentru că știm că ceea ce cerem este drept. Și am alipit copia epistolei lui Adrian ca să știi că spunem adevărul și în această privință. Și aceasta este copia.”"},{"v":8,"t":"După aceste cuvinte, autorul pomenit dă rescriptul în latină, pe care noi l-am tradus în greacă cât am putut mai exact. Sună astfel:"}];
window.LIB_LAZY["eusebiu-istoria#88"]=[{"v":1,"t":"Către Minuciu Fundan. Am primit o epistolă scrisă mie de Serenius Granian, un om preaslăvit, căruia i-ai urmat tu. Nu mi se pare drept ca lucrul să fie trecut fără cercetare, ca nu cumva oamenii să fie chinuiți și să se dea prilej denunțătorilor de a practica ticăloșia."},{"v":2,"t":"Dacă, deci, locuitorii provinciei pot susține limpede această cerere împotriva creștinilor, astfel încât să dea răspuns în fața unei instanțe, să urmeze numai această cale, dar să nu recurgă la cereri și strigăte ale oamenilor. Căci este mult mai potrivit, dacă cineva vrea să facă o învinuire, să cercetezi tu lucrul."},{"v":3,"t":"Dacă, deci, cineva îi învinuiește și arată că fac ceva împotriva legilor, tu dă hotărârea după gravitatea crimei. Dar, pe Hercule! Dacă cineva aduce o învinuire prin simplă calomnie, hotărăște în privința vinovăției lui și ai grijă să dai pedeapsa. Acesta este cuprinsul rescriptului lui Adrian."}];
window.LIB_LAZY["eusebiu-istoria#89"]=[{"v":1,"t":"Adrian murind după o domnie de douăzeci și unu de ani, i-a urmat în cârmuirea romanilor Antonin, numit Pios. În primul an al domniei lui, Telesfor a murit în al unsprezecelea an al episcopatului său și Higin a devenit episcop al Romei. Irineu însemnează că moartea lui Telesfor a fost făcută slăvită prin martiriu și, în aceeași legătură, spune că în vremea pomenitului episcop roman Higin, Valentin, întemeietorul unei secte a lui, și Cerdon, autorul rătăcirii lui Marcion, erau amândoi bine cunoscuți la Roma. Scrie astfel:"}];
window.LIB_LAZY["eusebiu-istoria#90"]=[{"v":1,"t":"„Căci Valentin a venit la Roma sub Higin, a înflorit sub Pius și a rămas până la Anicet. Cerdon, de asemenea, înaintașul lui Marcion, a intrat în Biserică în vremea lui Higin, al nouălea episcop, și a făcut mărturisire și a continuat în acest chip, când învățând în taină, când făcând din nou mărturisire și când denunțat pentru învățătură stricată și retrăgându-se din adunarea fraților.”"},{"v":2,"t":"Aceste cuvinte se găsesc în cartea a treia a lucrării Împotriva ereziilor. Și iarăși, în cartea întâi, vorbește astfel despre Cerdon: „Un anume Cerdon, care își luase sistemul de la urmașii lui Simon și venise la Roma sub Higin, al nouălea în succesiunea episcopală de la apostoli, a învățat că Dumnezeul vestit de lege și de proroci nu este tatăl Domnului nostru Isus Hristos. Căci cel dintâi era cunoscut, dar celălalt necunoscut; și cel dintâi era drept, dar celălalt bun. Marcion din Pont i-a urmat lui Cerdon și i-a dezvoltat învățătura, rostind hule fără rușine.”"},{"v":3,"t":"Același Irineu desfășoară cu cea mai mare vigoare prăpastia nepătrunsă a rătăcirilor lui Valentin cu privire la materie și dezvăluie răutatea lui, tainică și ascunsă ca un șarpe pitit în cuibul lui."},{"v":4,"t":"Și pe lângă acești oameni spune că mai era și altul care a trăit în acea epocă, Marcu cu numele, care era deosebit de priceput în artele magice. Și descrie și inițierile lor nesfințite și tainele lor urâte în cuvintele următoare:"},{"v":5,"t":"„Căci unii dintre ei pregătesc un pat de nuntă și săvârșesc un rit tainic cu anumite formule adresate celor care sunt inițiați și spun că este o căsătorie duhovnicească care se sărbătorește de ei, după asemănarea căsătoriilor de sus. Dar alții îi duc la apă și, în timp ce îi botează, rostesc următoarele cuvinte: În numele tatălui necunoscut al universului, în adevăr, mama tuturor lucrurilor, în cel care a coborât peste Isus. Alții rostesc nume ebraice, ca să-i încurce mai bine pe cei care sunt inițiați.”"},{"v":6,"t":"Dar Higin murind la sfârșitul celui de-al patrulea an al episcopatului său, Pius i-a urmat în cârmuirea bisericii Romei. În Alexandria Marcu a fost rânduit păstor, după ce Eumene ținuse slujba treisprezece ani în total. Și Marcu murind după ce ținuse slujba zece ani, i-a urmat Celadion în cârmuirea bisericii Alexandriei."},{"v":7,"t":"Și la Roma Pius a murit în al cincisprezecelea an al episcopatului său și Anicet a luat conducerea creștinilor de acolo. Hegesip însemnează că el însuși era la Roma în acest timp și că a rămas acolo până la episcopatul lui Eleuter."},{"v":8,"t":"Dar Iustin era deosebit de proeminent în acele zile. Sub chipul unui filozof, predica cuvântul dumnezeiesc și lupta pentru credință în scrierile lui. A scris și o lucrare împotriva lui Marcion, în care spune că acesta era în viață la vremea când scria."},{"v":9,"t":"Vorbește astfel: „Și este un anume Marcion din Pont, care chiar și acum își învață urmașii să socotească că este vreun alt Dumnezeu mai mare decât Creatorul. Și cu ajutorul demonilor a convins pe mulți de orice neam de oameni să rostească hulă și să tăgăduiască că făcătorul acestui univers este tatăl lui Hristos și să mărturisească că vreun altul, mai mare decât el, a fost creatorul. Și toți câți i-au urmat sunt, cum am spus, numiți creștini, după cum numele de filozofie se dă filozofilor, deși ar putea să nu aibă învățături comune.”"},{"v":10,"t":"La aceasta adaugă: „Și am scris și o lucrare împotriva tuturor ereziilor care au existat, pe care v-o vom da dacă doriți să o citiți.”"},{"v":11,"t":"Dar același Iustin s-a luptat cu cel mai mare succes împotriva grecilor și a adresat cuvântări care cuprind o apologie pentru credința noastră împăratului Antonin, numit Pios, și senatului roman. Căci trăia la Roma. Dar cine era și de unde venea arată în Apologia lui în cuvintele următoare."}];
window.LIB_LAZY["eusebiu-istoria#91"]=[{"v":1,"t":"„Către împăratul Titus Aelius Adrian Antonin Pios Cezar Augustus și către Verisim, fiul lui, filozoful, și către Lucius filozoful, fiul propriu al lui Cezar și fiul adoptiv al lui Pios, iubitor de învățătură, și către sfântul senat și către tot poporul roman, eu, Iustin, fiul lui Priscus și nepotul lui Baccius, din Flavia Neapolis din Palestina Siriei, vă prezint această cuvântare și cerere în folosul acelor oameni de orice neam care sunt urâți și prigoniți pe nedrept, eu însumi fiind unul dintre ei.” Și același împărat, aflând și de la alți frați din Asia de nedreptățile de tot felul pe care le sufereau din partea locuitorilor provinciei, a socotit cuvenit să adreseze următoarea rânduială Adunării Obștești a Asiei."}];
window.LIB_LAZY["eusebiu-istoria#92"]=[{"v":1,"t":"Împăratul Cezar Marcus Aurelius Antonin Augustus, Armenicus, Pontifex Maximus, pentru a cincisprezecea oară tribun, pentru a treia oară consul, către Adunarea Obștească a Asiei, salutare."},{"v":2,"t":"Știu că și zeii au grijă ca asemenea persoane să nu scape de descoperire. Căci ar pedepsi mult mai bine ei pe cei care nu vor să li se închine decât ați face voi."},{"v":3,"t":"Dar voi îi aruncați în încurcătură și, în timp ce îi învinuiți de ateism, nu faceți decât să-i întăriți în părerea pe care o țin. Ar fi într-adevăr mai de dorit pentru ei, când sunt învinuiți, să pară că mor pentru Dumnezeul lor decât să trăiască. De aceea ies și biruitori când își dau viețile mai degrabă decât să se supună poruncilor voastre."},{"v":4,"t":"Și în privința cutremurelor care au avut loc și mai au loc încă, nu este nepotrivit să vă mustrăm pe voi, care vă pierdeți curajul de câte ori se întâmplă și totuși sunteți deprinși să comparați purtarea voastră cu a lor."},{"v":5,"t":"Ei devin, într-adevăr, mai încrezători în Dumnezeu, în timp ce voi, în tot acest timp, neglijați, în aparentă neștiință, ceilalți zei și închinarea către Cel Nemuritor și asupriți și prigoniți până la moarte pe creștinii care I se închină."},{"v":6,"t":"Dar în privința acestor persoane, mulți dintre guvernatorii provinciilor au scris și preadumnezeiescului nostru tată, căruia el le-a scris în răspuns să nu supere pe acești oameni decât dacă s-ar arăta că încearcă ceva care atinge stăpânirea romană. Și mie mi-au trimis mulți comunicări despre acești oameni, dar le-am răspuns în același fel cum a făcut tatăl meu."},{"v":7,"t":"Dar dacă cineva stăruie încă în a aduce învinuiri împotriva unora dintre acești oameni ca atare, cel învinuit să fie achitat de învinuire, chiar dacă se arată că este unul dintre ei, dar învinuitorul să fie pedepsit. Publicat la Efes în Adunarea Obștească a Asiei."},{"v":8,"t":"De aceste lucruri este martor Melito, episcopul bisericii din Sardes și un om bine cunoscut în acel timp, după cum este limpede din cuvintele lui în Apologia pe care a adresat-o împăratului Ver în folosul învățăturii noastre."}];
window.LIB_LAZY["eusebiu-istoria#93"]=[{"v":1,"t":"În acest timp, pe când Anicet era în fruntea bisericii Romei, Irineu povestește că Policarp, care era încă în viață, a fost la Roma și că a avut o convorbire cu Anicet într-o chestiune privitoare la ziua sărbătorii pascale."},{"v":2,"t":"Și același scriitor dă o altă povestire despre Policarp pe care mă simt silit să o adaug la cea deja povestită despre el. Povestirea este luată din cartea a treia a lucrării lui Irineu Împotriva ereziilor și este următoarea:"},{"v":3,"t":"Dar și Policarp nu numai că a fost învățat de apostoli și a cunoscut mulți care văzuseră pe Hristos, ci a fost și rânduit de apostoli în Asia episcop al bisericii din Smirna."},{"v":4,"t":"Și noi l-am văzut în prima noastră tinerețe; căci a trăit mult timp și a murit, foarte bătrân, o moarte de martir slăvită și foarte vestită, învățând totdeauna lucrurile pe care le învățase de la apostoli, pe care le transmite și Biserica și care singure sunt adevărate."},{"v":5,"t":"Despre aceste lucruri mărturisesc toate bisericile Asiei, ca și cei care, până în timpul de față, i-au urmat lui Policarp, care a fost un martor mult mai vrednic de încredere și mai sigur al adevărului decât Valentin și Marcion și restul ereticilor. El a fost și la Roma în vremea lui Anicet și a făcut pe mulți să se întoarcă de la pomeniții eretici la Biserica lui Dumnezeu, vestind că a primit de la apostoli acest singur și unic sistem al adevărului care a fost transmis de Biserică."},{"v":6,"t":"Și sunt cei care au auzit de la el că Ioan, ucenicul Domnului, mergând să se scalde în Efes și văzând pe Cerint înăuntru, a ieșit în fugă din baie fără să se scalde, strigând: «Să fugim, ca să nu se prăbușească chiar baia, pentru că Cerint, dușmanul adevărului, este înăuntru.»"},{"v":7,"t":"Și Policarp însuși, când Marcion l-a întâlnit odată și a zis: «Ne cunoști?», a răspuns: «Cunosc pe întâi-născutul lui Satan.» Atâta prudență au avut apostolii și ucenicii lor încât nici măcar nu vorbeau cu vreunul dintre cei care stricau adevărul; după cum a zis și Pavel: «Pe omul eretic, după întâia și a doua mustrare, leapădă-l; știind că unul ca acesta este răsturnat și păcătuiește, fiind osândit de el însuși.» (Tit 3:10-11)"},{"v":8,"t":"Mai este și o foarte puternică epistolă a lui Policarp scrisă către filipeni, din care cei care vor și se îngrijesc de propria lor mântuire pot învăța caracterul credinței lui și predica adevărului. Aceasta este povestirea lui Irineu."},{"v":9,"t":"Dar Policarp, în pomenita epistolă către filipeni, care există încă, s-a slujit de unele mărturii luate din Prima Epistolă a lui Petru."},{"v":10,"t":"Și când Antonin, numit Pios, împlinise al douăzeci și doilea an al domniei lui, i-a urmat Marcus Aurelius Verus, fiul său, numit și Antonin, împreună cu fratele său Lucius."}];
window.LIB_LAZY["eusebiu-istoria#94"]=[{"v":1,"t":"În acest timp, când cele mai mari prigoane tulburau Asia, Policarp și-a încheiat viața prin martiriu. Dar socotesc cel mai important ca moartea lui, despre care există încă o povestire scrisă, să fie însemnată în această istorie."},{"v":2,"t":"Există o scrisoare, scrisă în numele bisericii pe care o prezida el însuși, către parohiile din Pont, care povestește întâmplările care i s-au petrecut, în cuvintele următoare:"},{"v":3,"t":"„Biserica lui Dumnezeu care locuiește în Filomelion și toate parohiile sfintei Biserici Catolice din fiecare loc; îndurare și pace și dragoste de la Dumnezeu Tatăl să se înmulțească. Vă scriem, frați, o povestire despre ce s-a întâmplat celor care au suferit martiriul și fericitului Policarp, care a pus capăt prigoanei, pecetluind-o, ca să zic așa, prin martiriul lui.”"},{"v":4,"t":"După aceste cuvinte, înainte de a da povestirea despre Policarp, însemnează întâmplările care au căzut peste restul martirilor și descriu marea tărie pe care au arătat-o în mijlocul durerilor lor. Căci spun că cei de față au fost loviți de uimire când i-au văzut sfâșiați cu biciuri până la cele mai dinăuntru vine și artere, așa încât părțile ascunse dinăuntru ale trupului, atât măruntaiele, cât și mădularele lor, erau scoase la vedere; și apoi culcați pe cochilii de mare și pe anumite frigări ascuțite și supuși la orice fel de pedeapsă și chin și, în sfârșit, aruncați ca hrană fiarelor sălbatice."},{"v":5,"t":"Și însemnează că preanobilul Germanic s-a distins în chip deosebit, biruind prin harul lui Dumnezeu frica de moartea trupească sădită de fire. Când proconsulul a vrut într-adevăr să-l convingă și i-a pus înainte tinerețea și l-a rugat, fiind foarte tânăr și voinic, să aibă milă de el însuși, nu a șovăit, ci a momit cu înfocare fiara spre el, aproape silind-o și iritând-o, ca să fie mai curând liberat din viața lor nedreaptă și fără lege."},{"v":6,"t":"După moartea lui slăvită, toată mulțimea, minunându-se de vitejia martirului iubit de Dumnezeu și de tăria întregului neam al creștinilor, a început să strige deodată: „Jos cu ateii; să fie căutat Policarp.”"},{"v":7,"t":"Și când s-a ridicat o foarte mare tulburare din pricina strigătelor, un anume frigian, Quintus cu numele, care venise de curând din Frigia, văzând fiarele și chinurile suplimentare, a fost lovit de lașitate și a renunțat la dobândirea mântuirii."},{"v":8,"t":"Dar pomenita epistolă arată că el, prea grăbit și fără cuvenita prudență, se năpustise înainte cu alții la tribunal, dar, când a fost prins, a dat o dovadă limpede tuturor că nu este drept ca asemenea persoane să se expună cu nechibzuință și neprevedere primejdiei. Astfel au ieșit lucrurile în legătură cu ei."},{"v":9,"t":"Dar preaminunatul Policarp, când a auzit întâi de aceste lucruri, a rămas netulburat, și-a păstrat mintea liniștită și neclintită și a hotărât să rămână în cetate. Dar fiind înduplecat de prietenii lui, care l-au rugat și l-au îndemnat să se retragă pe ascuns, a ieșit la o fermă nu departe de cetate și a stat acolo cu câțiva tovarăși, noaptea și ziua nefăcând nimic decât să se lupte cu Domnul în rugăciune, rugându-se și implorând și cerând pace pentru bisericile din toată lumea. Căci aceasta era totdeauna obiceiul lui."},{"v":10,"t":"Și cu trei zile înainte de arestarea lui, pe când se ruga, a văzut într-o vedenie noaptea perna de sub capul lui apucată deodată de foc și mistuită; și la această trezire a tâlcuit îndată vedenia celor de față, aproape prevestind ceea ce avea să se întâmple, și declarând limpede celor care erau cu el că va fi necesar ca, de dragul lui Hristos, să moară prin foc."},{"v":11,"t":"Apoi, pe măsură ce cei care îl căutau împingeau căutarea cu vigoare, se spune că a fost silit din nou de grija și dragostea fraților să meargă la o altă fermă. Acolo au venit urmăritorii lui după nu mult timp și au prins doi dintre slujitorii de acolo și l-au chinuit pe unul dintre ei ca să afle de la el ascunzătoarea lui Policarp."},{"v":12,"t":"Și venind târziu seara, l-au găsit culcat într-o cameră de sus, de unde ar fi putut merge într-o altă casă, dar nu a vrut, zicând: „Fie voia lui Dumnezeu.”"},{"v":13,"t":"Și când a aflat că sunt de față, după cum spune povestirea, a coborât și a vorbit cu ei cu o înfățișare foarte veselă și blândă, așa încât cei care nu cunoșteau deja omul au socotit că văd o minune când au observat vârsta lui înaintată și gravitatea și tăria purtării lui, și s-au minunat că se face atâta osteneală pentru a prinde un om ca el."},{"v":14,"t":"Dar el nu a șovăit, ci a dat îndată poruncă să li se întindă o masă. Apoi i-a poftit să ia parte la o masă îmbelșugată și le-a cerut un ceas ca să se poată ruga netulburat. Și când ei i-au dat voie, s-a ridicat și s-a rugat, fiind plin de harul Domnului, așa încât cei care erau de față și îl auzeau rugându-se au rămas uimiți și mulți dintre ei s-au pocăit acum că un bătrân atât de venerabil și evlavios era pe cale să fie dat la moarte."},{"v":15,"t":"Pe lângă aceste lucruri, povestirea despre el cuprinde următoarea istorisire: Dar când și-a încheiat în sfârșit rugăciunea, după ce și-a amintit de toți cei care veniseră vreodată în atingere cu el, mici și mari, vestiți și necunoscuți, și de toată Biserica Catolică din toată lumea, venind ceasul plecării, l-au urcat pe un măgar și l-au adus în cetate, fiind un mare Sabat. Și a fost întâmpinat de Irod, căpitanul poliției, și de tatăl lui Nicete, care l-au luat în carul lor și, așezându-se lângă el, s-au silit să-l convingă, zicând: «Ce rău este în a zice: Domnul Cezar, și a jertfi și a-ți scăpa viața?» El nu a răspuns la început; dar când au stăruit, a zis: «Nu am de gând să fac ce mă sfătuiți.»"},{"v":16,"t":"Și când nu au izbutit să-l convingă, au rostit cuvinte cumplite și l-au împins jos cu silnicie, așa încât, în timp ce cobora din car, și-a zdrelit pulpa. Dar, fără să se întoarcă, a mers pe drumul său cu iuțeală și repeziciune, ca și cum nu i s-ar fi întâmplat nimic, și a fost dus la stadion."},{"v":17,"t":"Dar era o asemenea zarvă în stadion încât nu mulți au auzit un glas din cer, care a venit către Policarp când intra în loc: «Fii tare, Policarp, și poartă-te bărbătește.» Și nimeni nu a văzut pe cel care vorbea, dar mulți dintre ai noștri au auzit glasul."},{"v":18,"t":"Și când a fost adus înainte, a fost o mare zarvă, pe măsură ce auzeau că Policarp a fost prins. În sfârșit, când s-a apropiat, proconsulul a întrebat dacă este Policarp. Și când a mărturisit că este, s-a silit să-l convingă să se lepede, zicând: «Ia seama la vârsta ta» și alte asemenea lucruri pe care este obiceiul lor să le spună: «Jură pe geniul lui Cezar; pocăiește-te și spune: Jos cu ateii.»"},{"v":19,"t":"Dar Policarp, privind cu înfățișare demnă la toată mulțimea adunată în stadion, le-a făcut un semn cu mâna și a gemut și, ridicându-și ochii spre cer, a zis: «Jos cu ateii.»"},{"v":20,"t":"Dar când magistratul l-a apăsat și a zis: «Jură și te voi elibera; hulește pe Hristos», Policarp a zis: «Optzeci și șase de ani Îi slujesc și nu mi-a făcut niciun rău; cum, deci, aș putea huli pe Regele meu care m-a mântuit?»"},{"v":21,"t":"Dar când a stăruit din nou și a zis: «Jură pe geniul lui Cezar», Policarp a răspuns: «Dacă îți închipui în zadar că voi jura pe geniul lui Cezar, cum zici, prefăcându-te că nu știi cine sunt, ascultă limpede: sunt creștin. Dar dacă dorești să înveți doctrina creștinismului, rânduiește o zi și ascultă.»"},{"v":22,"t":"Proconsulul a zis: «Convinge poporul.» Dar Policarp a zis: «Cât despre tine, te-am socotit vrednic de o explicație; căci am fost învățați să dăm cârmuitorilor și autorităților rânduite de Dumnezeu cinstea care se cuvine, atât cât nu ne vatămă; dar cât despre aceștia, nu-i socotesc persoanele potrivite față de care să-mi fac apărarea.»"},{"v":23,"t":"Dar proconsulul a zis: «Am fiare sălbatice; te voi arunca la ele dacă nu te pocăiești.» Dar el a zis: «Cheamă-le; căci pocăința de la mai bine la mai rău este o schimbare pe care nu o putem face. Dar este un lucru nobil să te întorci de la răutate la dreptate.»"},{"v":24,"t":"Dar el i-a zis din nou: «Dacă disprețuiești fiarele sălbatice, voi face să fii mistuit de foc, dacă nu te pocăiești.» Dar Policarp a zis: «Amenințai cu un foc care arde un ceas și după puțin se stinge; căci nu cunoști focul judecății viitoare și al pedepsei veșnice care este păstrată celor nelegiuiți. Dar de ce zăboveși? Fă ce vrei.»"},{"v":25,"t":"Spunând aceste cuvinte și altele pe lângă ele, a fost plin de curaj și bucurie și fața lui era acoperită de har, așa încât nu numai că nu a fost înspăimântat și tulburat de cuvintele care i se spuneau, ci, dimpotrivă, proconsulul a rămas uimit și și-a trimis crainicul să vestească de trei ori în mijlocul stadionului: «Policarp a mărturisit că este creștin.»"},{"v":26,"t":"Și când acest lucru a fost vestit de crainic, toată mulțimea, atât de neamuri, cât și de iudei, care locuiau în Smirna, a strigat cu mânie nestăpânită și cu mare strigăt: «Acesta este învățătorul Asiei, tatăl creștinilor, răsturnătorul zeilor noștri, care învață pe mulți să nu jertfească și să nu se închine.»"},{"v":27,"t":"Când au spus acestea, au strigat și au cerut asiarhului Filip să dea drumul unui leu asupra lui Policarp. Dar el a spus că nu-i este îngăduit, de vreme ce închisese jocurile. Atunci au socotit cuvenit să strige într-un glas ca Policarp să fie ars de viu."},{"v":28,"t":"Căci era necesar să se împlinească vedenia care îi fusese arătată cu privire la perna lui, când a văzut-o arzând pe când se ruga, și s-a întors și a spus profetic credincioșilor care erau cu el: «Trebuie să fiu ars de viu.»"},{"v":29,"t":"Aceste lucruri s-au făcut cu mare iuțeală — mai repede decât s-au spus — mulțimile adunând îndată din ateliere și băi lemne și vreascuri, iudeii fiind deosebit de râvnitori în lucrare, cum le este obiceiul."},{"v":30,"t":"Dar când rugul a fost gata, scoțându-și toate hainele de deasupra și desfăcându-și cingătoarea, s-a străduit și să-și scoată încălțămintea, deși nu o făcuse niciodată înainte, din pricina străduinței pe care o făcea fiecare dintre credincioși să se atingă întâi de pielea lui; căci fusese tratat cu toată cinstea din pricina vieții lui virtuoase încă înainte de a-i veni părul cărunt."},{"v":31,"t":"Îndată, deci, materialele pregătite pentru rug au fost așezate în jurul lui; și pe când erau gata să-l țintuiască și de stâlp, a zis: «Lăsați-mă așa; căci Cel care mi-a dat putere să îndur focul îmi va da putere să rămân în foc nemișcat și fără să fiu legat de voi cu piroane.» Astfel nu l-au țintuit, ci l-au legat."},{"v":32,"t":"Și el, cu mâinile la spate și legat ca un berbec nobil luat dintr-o turmă mare, o ardere de tot primită de Dumnezeul atotputernic, a zis:"},{"v":33,"t":"«Tată al Fiului Tău iubit și binecuvântat Isus Hristos, prin care am primit cunoașterea Ta, Dumnezeul îngerilor și al puterilor și al întregii creații și al întregului neam al celor drepți care trăiesc în prezența Ta, Te binecuvântez că m-ai socotit vrednic de această zi și de acest ceas, ca să primesc o parte în numărul martirilor, în paharul lui Hristos, spre învierea vieții veșnice, și a sufletului, și a trupului, în nemurirea Duhului Sfânt."},{"v":34,"t":"Printre aceștia să fiu primit înaintea Ta în această zi, într-o jertfă bogată și primită, după cum Tu, Dumnezeul credincios și adevărat, ai pregătit mai dinainte și ai descoperit și ai împlinit."},{"v":35,"t":"De aceea Te laud și pentru toate; Te binecuvântez, Te slăvesc, prin Marele Preot veșnic, Isus Hristos, Fiul Tău iubit, prin care, cu El, în Duhul Sfânt, să fie slavă Ție, și acum, și în veacurile ce vor veni, Amin.»"},{"v":36,"t":"Când și-a rostit Amin și și-a încheiat rugăciunea, cei care aprindeau focul au dat foc și, pe măsură ce o mare flacără a izbucnit, noi, cărora ne-a fost dat să vedem, am văzut o minune și am fost păstrați ca să povestim celorlalți ce s-a întâmplat."},{"v":37,"t":"Căci focul prezenta înfățișarea unei bolți, ca pânza unei corăbii umflată de vânt, și a făcut un zid în jurul trupului martirului și era în mijloc nu ca o carne arzând, ci ca aur și argint rafinate în cuptor. Căci am simțit un miros atât de bun, ca de fumul tămâii sau al altor mirodenii scumpe."},{"v":38,"t":"Astfel, în sfârșit, oamenii fără lege, când au văzut că trupul nu poate fi mistuit de foc, au poruncit unui călău să se apropie și să-l străpungă cu sabia."},{"v":39,"t":"Și când a făcut aceasta, a ieșit o cantitate de sânge așa încât a stins focul; și toată mulțimea s-a minunat că poate fi o asemenea deosebire între necredincioși și cei aleși, dintre care acest om era unul, cel mai minunat învățător în vremurile noastre, apostolic și profetic, care a fost episcop al Bisericii Catolice din Smirna. Căci fiecare cuvânt care a ieșit din gura lui s-a împlinit și se va împlini."},{"v":40,"t":"Dar Cel Rău, gelos și pizmaș, potrivnicul neamului celor drepți, când a văzut mărimea martiriului lui și viața lui fără prihană de la început și când l-a văzut încununat cu cununa nemuririi și luând un premiu de necontestat, a avut grijă ca nici măcar trupul lui să nu fie luat de noi, deși mulți doreau să o facă și să aibă părtășie cu sfânta lui carne."},{"v":41,"t":"De aceea unii au sugerat în taină lui Nicete, tatăl lui Irod și fratele Alcei, să roage magistratul să nu dea trupul lui, «ca nu cumva», se spunea, «să părăsească pe Cel răstignit și să înceapă să se închine acestui om». Au spus aceste lucruri la sugestia și îndemnul iudeilor, care au și vegheat când ne pregăteam să-l luăm din foc, neștiind că nu vom putea niciodată nici să-L părăsim pe Hristos, care a pătimit pentru mântuirea întregii lumi a celor care se mântuiesc, nici să ne închinăm vreunui altul."},{"v":42,"t":"Căci noi ne închinăm Aceluia care este Fiul lui Dumnezeu, dar pe martiri, ca pe ucenici și imitatori ai Domnului, îi iubim după cum merită, din pricina neegalatei lor afecțiuni pentru propriul lor rege și învățător. Să fim și noi făcuți părtași și împreună-ucenici cu ei."},{"v":43,"t":"Centurionul, deci, când a văzut gâlceava arătată de iudei, l-a pus în mijloc și l-a ars, după obiceiul lor. Și astfel am adunat noi mai târziu oasele lui, care erau mai de preț decât pietrele scumpe și mai de cinstit decât aurul, și le-am așezat într-un loc potrivit."},{"v":44,"t":"Acolo ne va îngădui Domnul să ne adunăm cât vom putea, în veselie și bucurie, ca să prăznuim ziua de naștere a martiriului lui, spre pomenirea celor care au luptat deja și spre deprinderea și pregătirea celor care vor face la fel după aceea."},{"v":45,"t":"Acestea sunt întâmplările care au căzut peste fericitul Policarp, care a suferit martiriul la Smirna împreună cu cei unsprezece din Filadelfia. Acest singur om este pomenit mai mult decât ceilalți de toți, așa încât chiar și de păgâni se vorbește despre el în fiecare loc."},{"v":46,"t":"De un asemenea sfârșit a fost socotit vrednic preaminunatul și apostolicul Policarp, după cum este însemnat de frații bisericii din Smirna în epistola lor pe care am pomenit-o. În același volum despre el sunt alipite și alte martiriuri care au avut loc în aceeași cetate, Smirna, cam în aceeași perioadă cu martiriul lui Policarp. Printre ele și Metrodor, care pare să fi fost un prozelit al sectei marcioniților, a suferit moartea prin foc."},{"v":47,"t":"Un martir vestit al acelor vremuri a fost un anume om numit Pioniu. Cei care doresc să cunoască mărturisirile lui deosebite și îndrăzneala vorbirii lui și apărările lui în folosul credinței înaintea poporului și a cârmuitorilor și cuvântările lui instructive și, pe lângă acestea, salutările lui către cei care cedaseră ispitei în prigoană și cuvintele de îmbărbătare pe care le-a adresat fraților care veneau să-l viziteze în temniță și chinurile pe care le-a îndurat pe deasupra și, pe lângă acestea, suferințele și țintuirile și tăria lui pe rug și moartea lui după toate încercările ieșite din comun — pe aceștia îi trimitem la acea epistolă care a fost dată în Martiriile celor din vechime, adunate de noi, și care cuprinde o povestire foarte deplină despre el."},{"v":48,"t":"Și mai sunt păstrate și însemnări despre alții care au suferit martiriul la Pergam, o cetate a Asiei — despre Carp și Papil și o femeie numită Agatonice, care, după multe și slăvite mărturisiri, și-au încheiat viețile cu slavă."}];
window.LIB_LAZY["eusebiu-istoria#95"]=[{"v":1,"t":"Pe la acest timp Iustin, pe care l-am pomenit chiar mai sus, după ce a adresat o a doua lucrare în folosul învățăturilor noastre cârmuitorilor numiți deja, a fost încununat cu martiriu dumnezeiesc, în urma unei uneltiri puse la cale împotriva lui de Crescent, un filozof care imita viața și purtările cinicilor, al căror nume îl purta. După ce Iustin îl combătuse de multe ori în discuții publice, a câștigat prin martiriul lui premiul biruinței, murind pentru adevărul pe care îl predica."},{"v":2,"t":"Și el însuși, un om foarte învățat în adevăr, în Apologia lui deja pomenită prevestește limpede cum avea să i se întâmple, deși nu se întâmplase încă."},{"v":3,"t":"Cuvintele lui sunt următoarele: Și eu, deci, mă aștept să fiu uneltit împotriva și pus în butuci de vreunul dintre cei pe care i-am numit, sau poate de Crescent, acel om nefilozofic și plin de slavă deșartă. Căci omul nu este vrednic să fie numit filozof care dă pe față mărturie împotriva celor despre care nu știe nimic, declarând, ca să captiveze și să placă mulțimii, că creștinii sunt atei și nelegiuiți."},{"v":4,"t":"Făcând aceasta greșește mult. Căci dacă ne atacă fără să fi citit învățăturile lui Hristos, este cu totul stricat și este mult mai rău decât cei neînvățați, care adesea se feresc să discute și să dea mărturie mincinoasă despre lucruri pe care nu le înțeleg. Și dacă le-a citit și nu înțelege măreția care este în ele, sau, înțelegând-o, face aceste lucruri ca să nu fie bănuit că este adept, este mult mai josnic și cu totul stricat, fiind înrobit aplauzelor vulgare și fricii neraționale."},{"v":5,"t":"Căci aș vrea să știți că, atunci când am propus unele întrebări de acest fel și l-am întrebat în privința lor, am aflat și am dovedit că într-adevăr nu știe nimic. Și ca să arăt că spun adevărul, sunt gata, dacă aceste discuții nu v-au fost raportate, să discut din nou întrebările în prezența voastră. Și aceasta ar fi într-adevăr o faptă vrednică de un împărat."},{"v":6,"t":"Dar dacă întrebările mele și răspunsurile lui v-au fost aduse la cunoștință, vă este limpede că nu știe nimic despre treburile noastre; sau dacă știe, dar nu cutează să vorbească din pricina celor care îl aud, se arată, cum am spus deja, nu filozof, ci un om plin de slavă deșartă, care într-adevăr nu ia în seamă nici acea preaminunată spusă a lui Socrate. Acestea sunt cuvintele lui Iustin."},{"v":7,"t":"Și că și-a întâmpinat moartea după cum prevestise că o va face, în urma uneltirilor lui Crescent, este spus de Tațian, un om care la începutul vieții a ținut prelegeri despre științele grecilor și a câștigat nu puțină faimă în ele și care a lăsat multe monumente ale lui însuși în scrierile lui. Însemnează acest fapt în lucrarea lui împotriva grecilor, unde scrie astfel: „Și acel preaminunat Iustin a declarat cu adevărat că pomeniții oameni erau ca niște tâlhari.”"},{"v":8,"t":"Apoi, după ce face niște observații despre filozofi, continuă astfel: Crescent, într-adevăr, care și-a făcut cuib în marea cetate, i-a întrecut pe toți în pofta lui împotriva firii și era cu totul dedat iubirii de bani."},{"v":9,"t":"Și cel care învăța că moartea trebuie disprețuită era el însuși atât de mult înspăimântat de ea încât s-a silit să-i dea moartea, ca pe un mare rău, lui Iustin, pentru că acesta, predicând adevărul, dovedise că filozofii erau lacomi și înșelători. Și aceasta a fost pricina martiriului lui Iustin."}];
window.LIB_LAZY["eusebiu-istoria#96"]=[{"v":1,"t":"Același om, înainte de lupta lui, pomenește în prima lui Apologie pe alții care au suferit martiriul înaintea lui și însemnează foarte potrivit următoarele întâmplări."},{"v":2,"t":"Scrie astfel: O anume femeie trăia cu un soț destrăbălat; și ea însăși fusese mai înainte de același fel. Dar când a ajuns la cunoașterea învățăturilor lui Hristos, s-a făcut cumpătată și s-a silit să-și convingă soțul să fie și el cumpătat, repetându-i învățăturile și declarându-i pedeapsa în focul veșnic care va veni peste cei care nu trăiesc cumpătat și potrivit rațiunii drepte."},{"v":3,"t":"Dar el, continuând în aceleași excese, și-a înstrăinat nevasta prin purtarea lui. Căci ea, în cele din urmă, socotind că este rău să trăiască ca nevastă cu un om care, împotriva legii firii și a dreptății, căuta toate mijloacele cu putință de plăcere, a dorit să divorțeze de el."},{"v":4,"t":"Și când a fost rugată cu stăruință de prietenii ei, care o sfătuiau să mai rămână cu el, pe motiv că soțul ei ar putea cândva să dea nădejde de îndreptare, și-a făcut silă și a rămas."},{"v":5,"t":"Dar când soțul ei a plecat la Alexandria și s-a răspândit vestea că se poartă și mai rău, ea — ca să nu devină, continuând în căsătorie și împărțind masa și patul lui, părtașă la fărădelegea și nelegiuirea lui — i-a dat ceea ce numim o carte de despărțire și l-a părăsit."},{"v":6,"t":"Dar nobilul și excelentul ei soț — în loc să se bucure, cum ar fi trebuit, că ea se lepădase de acele fapte pe care le făcuse mai înainte cu nechibzuință cu slujitorii și argații, când se desfăta în beție și în orice viciu, și că dorea ca și el să se lepede de ele — când ea a plecat de la el împotriva voinței lui, a adus o învinuire împotriva ei, declarând că este creștină."},{"v":7,"t":"Și ea a cerut vouă, împăratului, să i se îngăduie să-și rânduiască mai întâi treburile și apoi, după rânduirea treburilor ei, să-și facă apărarea împotriva învinuirii. Și voi ați îngăduit aceasta."},{"v":8,"t":"Dar cel care fusese odată soțul ei, neputând să o mai urmărească, și-a îndreptat atacurile împotriva unui anume Ptolemeu, care îi fusese învățător în învățăturile creștinismului și pe care Urbiciu îl pedepsise. Împotriva lui a procedat în felul următor:"},{"v":9,"t":"A convins un centurion care era prietenul lui să-l arunce pe Ptolemeu în temniță și să-l ia și să-l întrebe numai aceasta: este creștin? Și când Ptolemeu, care era iubitor de adevăr și nu de fire înșelătoare și mincinoasă, a mărturisit că este creștin, centurionul l-a legat și l-a pedepsit multă vreme în temniță."},{"v":10,"t":"Și, în sfârșit, când omul a fost adus înaintea lui Urbiciu, a fost întrebat de asemenea numai aceasta: este creștin? Și iarăși, conștient de binefacerile de care se bucura prin învățătura lui Hristos, și-a mărturisit școala în virtutea dumnezeiască."},{"v":11,"t":"Căci oricine tăgăduiește că este creștin, ori tăgăduiește pentru că disprețuiește creștinismul, ori se ferește de mărturisire pentru că este conștient că este nevrednic și străin de el; niciunul dintre acestea nefiind cazul adevăratului creștin."},{"v":12,"t":"Și când Urbiciu a poruncit să fie dus la pedeapsă, un anume Lucius, care era și el creștin, văzând judecata dată atât de nedrept, a zis lui Urbiciu: «De ce ai pedepsit pe acest om care nu este adulter, nici desfrânat, nici ucigaș, nici hoț, nici tâlhar și nici nu a fost dovedit că a săvârșit vreo crimă, ci a mărturisit că poartă numele de creștin? Nu judeci, Urbiciu, într-un chip potrivit împăratului Pios, sau fiului filozof al lui Cezar, sau sfântului senat.»"},{"v":13,"t":"Și, fără să dea alt răspuns, a zis lui Lucius: «Și tu îmi pari unul dintre ei.» Și când Lucius a zis: «Cu siguranță», a poruncit din nou ca și el să fie dus la pedeapsă. Dar el și-a arătat mulțumirea, căci era eliberat, a adăugat, de asemenea cârmuitori răi și mergea la Tatăl și Regele bun, Dumnezeu. Și încă un al treilea, venind înainte, a fost osândit să fie pedepsit."},{"v":14,"t":"La aceasta, Iustin adaugă foarte potrivit și în consecvență cuvintele pe care le-am citat mai sus, zicând: „Și eu, deci, mă aștept să fiu uneltit împotriva de către vreunul dintre cei pe care i-am numit”, etc."}];
window.LIB_LAZY["eusebiu-istoria#97"]=[{"v":1,"t":"Acest scriitor ne-a lăsat multe monumente ale unei minți educate și exersate în lucrurile dumnezeiești, pline de materie folositoare de tot felul. Trimitem la ele pe cei studioși, notând pe măsură ce înaintăm pe cele care au ajuns la cunoștința noastră."},{"v":2,"t":"Există o anume cuvântare a lui în apărarea învățăturii noastre, adresată lui Antonin, poreclit Pios, și fiilor lui și senatului roman. O altă lucrare cuprinde a doua lui Apologie în folosul credinței noastre, pe care a oferit-o aceluia care i-a urmat împăratului pomenit și care purta același nume, Antonin Verus, cel ale cărui vremuri le însemnăm acum."},{"v":3,"t":"De asemenea o altă lucrare împotriva grecilor, în care discută pe larg cele mai multe dintre chestiunile aflate în dispută între noi și filozofii greci și discută firea demonilor. Nu este necesar să adaug aici niciunul dintre aceste lucruri."},{"v":4,"t":"Și încă o altă lucrare a lui împotriva grecilor a ajuns până la noi, căreia i-a dat titlul Combatere. Și pe lângă acestea alta, Despre suveranitatea lui Dumnezeu, pe care o întemeiază nu numai din Scripturile noastre, ci și din cărțile grecilor."},{"v":5,"t":"Încă și o lucrare intitulată Psaltes și o altă disputare Despre suflet, în care, după ce pune felurite întrebări despre problema în discuție, dă părerile filozofilor greci, făgăduind să o combată și să-și prezinte propria părere într-o altă lucrare."},{"v":6,"t":"A alcătuit și un dialog împotriva iudeilor, pe care l-a ținut în cetatea Efes cu Trifon, un om foarte distins între evreii acelei vremi. În el arată cum harul dumnezeiesc l-a îndemnat la învățătura credinței și cu cât zel urmărise mai înainte studiile filozofice și cât de înfocat căutase adevărul."},{"v":7,"t":"Și însemnează despre iudei, în aceeași lucrare, că uneltiseră împotriva învățăturii lui Hristos, afirmând aceleași lucruri împotriva lui Trifon: „Nu numai că nu v-ați pocăit de răutatea pe care o săvârșiserăți, ci ați ales în acel timp oameni aleși și i-ați trimis de la Ierusalim prin toată țara, ca să vestească că a apărut erezia fără Dumnezeu a creștinilor și să-i învinuiască de acele lucruri pe care toți cei neștiutori de noi le spun împotriva noastră, așa încât ați devenit pricinile nu numai ale propriei voastre nedreptăți, ci și ale tuturor celorlalți oameni.”"},{"v":8,"t":"Scrie și că până în vremea lui străluceau în Biserică daruri proorocești. Și pomenește Apocalipsa lui Ioan, spunând limpede că este a apostolului. Se referă și la anumite declarații proorocești și îl învinuiește pe Trifon pe motiv că iudeii le tăiaseră din Scriptură. Foarte multe alte lucrări ale lui sunt încă în mâinile multora dintre frați."},{"v":9,"t":"Și cuvântările omului au fost socotite atât de vrednice de studiu chiar de cei din vechime încât Irineu citează cuvintele lui: de pildă, în cartea a patra a lucrării sale Împotriva ereziilor, unde scrie astfel: „Și Iustin spune bine în lucrarea lui împotriva lui Marcion că nu ar fi crezut pe Domnul însuși dacă ar fi predicat un alt Dumnezeu pe lângă Creator”; și iarăși în cartea a cincea a aceleiași lucrări spune: „Și Iustin a spus bine că înainte de venirea Domnului, Satan nu a cutezat niciodată să-L hulească pe Dumnezeu, pentru că nu-și cunoștea încă osânda.”"},{"v":10,"t":"Aceste lucruri am socotit necesar să le spun ca să îndemn pe cei studioși să parcurgă cu sârguință lucrările lui. Atât despre el."}];
window.LIB_LAZY["eusebiu-istoria#98"]=[{"v":1,"t":"În al optulea an al pomenitei domnii, Soter i-a urmat lui Anicet ca episcop al bisericii Romei, după ce acesta din urmă ținuse slujba unsprezece ani în total. Dar când Celadion prezidase biserica Alexandriei paisprezece ani, i-a urmat Agripin."}];
window.LIB_LAZY["eusebiu-istoria#99"]=[{"v":1,"t":"În acel timp, în biserica din Antiohia, Teofil era bine cunoscut ca al șaselea de la apostoli. Căci Corneliu, care i-a urmat lui Heros, a fost al patrulea, iar după el Eros, al cincilea în ordine, ținuse slujba de episcop."}];
window.LIB_LAZY["eusebiu-istoria#100"]=[{"v":1,"t":"În acel timp au înflorit în Biserică Hegesip, pe care îl cunoaștem din cele dinainte, și Dionisie, episcopul Corintului, și un alt episcop, Pinit al Cretei, și pe lângă aceștia, Filip și Apolinarie și Melito și Musan și Modest și, în sfârșit, Irineu. De la ei a ajuns la noi în scris credința sănătoasă și ortodoxă primită din tradiția apostolică."}];
window.LIB_LAZY["eusebiu-istoria#101"]=[{"v":1,"t":"Hegesip, în cele cinci cărți de Memorii care au ajuns până la noi, ne-a lăsat o însemnare foarte deplină a propriilor lui păreri. În ele spune că într-o călătorie la Roma a întâlnit foarte mulți episcopi și că a primit aceeași învățătură de la toți. Este cuvenit să auzim ce spune după ce face niște observații despre epistola lui Clement către corinteni."},{"v":2,"t":"Cuvintele lui sunt următoarele: Și biserica Corintului a continuat în credința adevărată până când Primus a fost episcop în Corint. Am vorbit cu ei în drumul meu spre Roma și am rămas cu corintenii multe zile, în care ne-am împrospătat unii pe alții în învățătura adevărată."},{"v":3,"t":"Și când am ajuns la Roma, am rămas acolo până la Anicet, al cărui diacon era Eleuter. Și lui Anicet i-a urmat Soter și lui Eleuter. În fiecare succesiune și în fiecare cetate este ținut ceea ce este predicat de lege și de proroci și de Domnul."},{"v":4,"t":"Același autor descrie și începuturile ereziilor care s-au ridicat în vremea lui, în cuvintele următoare: Și după ce Iacov Cel Drept a suferit martiriul, cum suferise și Domnul din aceeași pricină, Simeon, fiul unchiului Domnului, Cleopa, a fost rânduit următorul episcop. Toți l-au propus ca al doilea episcop pentru că era văr al Domnului. De aceea au numit Biserica fecioară, căci nu era încă stricată de cuvântări deșarte."},{"v":5,"t":"Dar Tebutis, pentru că nu a fost făcut episcop, a început s-o strice. Și el se trăgea din cele șapte secte din popor, ca Simon, din care au venit simonienii, și Cleobiu, din care au venit cleobienii, și Dositei, din care au venit dositeenii, și Gorteu, din care au venit gorațenii, și Masboteu, din care au venit masbotenii. Din ei au ieșit menandrienii, marcioniții, carpocrațienii, valentinienii, basilidienii și saturnilienii. Fiecare a introdus în taină și deosebit propria lui părere deosebită. Din ei au venit hristoși mincinoși, proroci mincinoși, apostoli mincinoși, care au dezbinat unitatea Bisericii prin învățături stricate rostite împotriva lui Dumnezeu și împotriva Hristosului Său."},{"v":6,"t":"Același scriitor însemnează și ereziile străvechi care s-au ridicat între iudei, în cuvintele următoare: „Erau, pe lângă aceasta, felurite păreri în tăierea împrejur, între copiii lui Israel. Următoarele erau cele care s-au împotrivit seminției lui Iuda și Hristosului: esenienii, galileenii, hemerobaptiștii, masbotenii, samaritenii, saducheii, fariseii.”"},{"v":7,"t":"Și a scris despre multe alte chestiuni, pe care le-am pomenit deja în parte, introducând povestirile la locurile lor potrivite. Și din Evanghelia siriacă după evrei citează unele pasaje în limba ebraică, arătând că era un convertit dintre evrei, și pomenește alte lucruri luate din tradiția nescrisă a iudeilor."},{"v":8,"t":"Și nu numai el, ci și Irineu și toată ceata celor din vechime numeau Pildele lui Solomon Înțelepciune prea-virtuoasă. Și, vorbind despre cărțile numite apocrife, însemnează că unele dintre ele au fost alcătuite în vremea lui de unii eretici. Dar să trecem acum la altul."}];
window.LIB_LAZY["eusebiu-istoria#102"]=[{"v":1,"t":"Și mai întâi trebuie să vorbim despre Dionisie, care a fost rânduit episcop al bisericii din Corint și a împărtășit cu dărnicie din osteneala lui insuflată nu numai ai lui, ci și celor din țări străine, și a adus cel mai mare folos tuturor prin epistolele catolice pe care le-a scris bisericilor."},{"v":2,"t":"Printre acestea este cea adresată lacedemonienilor, cuprinzând învățătură în credința ortodoxă și un îndemn la pace și unitate; cea adresată și atenienilor, stârnindu-i la credință și la viața rânduită de Evanghelie, pe care îi învinuiește că o socotesc puțin, ca și cum ar fi aproape apostaziat de la credință de la martiriul cârmuitorului lor Publiu, care avusese loc în prigoanele acelor zile."},{"v":3,"t":"Pomenește și pe Cuadrat, spunând că a fost rânduit episcop al lor după martiriul lui Publiu și mărturisind că prin râvna lui au fost aduși din nou laolaltă și credința lor a reînviat. Însemnează, pe lângă aceasta, că Dionisie Areopagitul, care a fost convertit la credință de apostolul Pavel, după spusa din Faptele Apostolilor, a căpătat cel dintâi episcopatul bisericii din Atena."},{"v":4,"t":"Și mai există o altă epistolă a lui adresată nicomedienilor, în care atacă erezia lui Marcion și stă tare lângă canonul adevărului."},{"v":5,"t":"Scriind și bisericii care este în Gortina, împreună cu celelalte parohii din Creta, laudă pe episcopul lor Filip, din pricina multelor fapte de tărie despre care se mărturisește că au fost făcute de biserică sub el, și îi avertizează să se păzească de rătăcirile ereticilor."},{"v":6,"t":"Și scriind bisericii care este în Amastris, împreună cu cele din Pont, se referă la Bachilide și Elpist, ca unii care l-au îndemnat să scrie, și adaugă tâlcuiri ale unor pasaje din Scripturile dumnezeiești și pomenește pe nume pe episcopul lor Palma. Le dă multe sfaturi și în privința căsătoriei și a castității și le poruncește să primească pe cei care se întorc din nou după orice cădere, fie că este greșeală, fie erezie."},{"v":7,"t":"Printre acestea este inserată și o altă epistolă adresată cnosienilor, în care îl îndeamnă pe Pinit, episcopul parohiei, să nu pună pe frați o povară grea și silnică în privința castității, ci să țină seama de slăbiciunea mulțimii."},{"v":8,"t":"Pinit, răspunzând la această epistolă, îl admiră și îl laudă pe Dionisie, dar îl îndeamnă la rândul lui să împărtășească cândva hrană mai solidă și să hrănească poporul de sub el, când va scrie din nou, cu învățătură mai înaintată, ca să nu fie hrăniți necontenit cu aceste învățături de lapte și să îmbătrânească pe nesimțite sub o creștere potrivită pentru copii. În această epistolă ortodoxia lui Pinit în credință și grija lui pentru bunăstarea celor puși sub el, învățătura lui și înțelegerea lui a lucrurilor dumnezeiești sunt descoperite ca într-o icoană desăvârșită."},{"v":9,"t":"Există și o altă epistolă scrisă de Dionisie romanilor și adresată lui Soter, care era episcop în acel timp. Nu putem face mai bine decât să alipim unele pasaje din această epistolă, în care laudă practica romanilor, care a fost păstrată până la prigoana din zilele noastre. Cuvintele lui sunt următoarele:"},{"v":10,"t":"„Căci de la început a fost practica voastră să faceți bine tuturor fraților în felurite chipuri și să trimiteți ajutoare multor biserici din fiecare cetate. Astfel ușurând nevoia celor lipsiți și făcând rânduială pentru frații din mine prin darurile pe care le-ați trimis de la început, voi, romanii, păstrați obiceiurile moștenite ale romanilor, pe care fericitul vostru episcop Soter nu numai că le-a păstrat, ci le-a și sporit, dând belșug de provizii sfinților și îmbărbătând pe frații din străinătate cu cuvinte binecuvântate, ca un tată iubitor pe copiii lui.”"},{"v":11,"t":"În aceeași epistolă pomenește și epistola lui Clement către corinteni, arătând că a fost obiceiul de la început să fie citită în biserică. Cuvintele lui sunt următoarele: „Astăzi am petrecut sfânta zi a Domnului, în care am citit epistola voastră. Din ea, ori de câte ori o citim, vom putea totdeauna să tragem sfat, ca și din epistola dinainte, care ne-a fost scrisă prin Clement.”"},{"v":12,"t":"Același scriitor vorbește și astfel despre propriile lui epistole, pretinzând că fuseseră mutilate: „Cum frații doreau să scriu epistole, am scris. Și aceste epistole apostolii diavolului le-au umplut de neghină, tăind unele lucruri și adăugând altele. Pentru ei este păstrat un vai. Nu este, deci, de mirare dacă unii au încercat să falsifice și scrierile Domnului, de vreme ce au făcut planuri chiar împotriva unor scrieri care sunt de mai puțină însemnătate.” Există, pe lângă acestea, o altă epistolă a lui Dionisie, scrisă Hrisoforei, o soră foarte credincioasă. În ea scrie ce este potrivit și îi împărtășește și hrana duhovnicească cuvenită. Atât despre Dionisie."}];
window.LIB_LAZY["eusebiu-istoria#103"]=[{"v":1,"t":"De Teofil, pe care l-am pomenit ca episcop al bisericii din Antiohia, există trei lucrări elementare adresate lui Autolic; și o altă scriere intitulată Împotriva ereziei lui Hermogene, în care se slujește de mărturii din Apocalipsa lui Ioan, și, în sfârșit, unele alte cărți catehetice."},{"v":2,"t":"Și cum ereticii, nu mai puțin atunci decât în alte vremuri, erau ca neghina, nimicind recolta curată a învățăturii apostolice, păstorii bisericilor de pretutindeni s-au grăbit să-i țină în frâu ca pe fiare sălbatice departe de staulul lui Hristos, când prin avertismente și îndemnuri către frați, când luptând mai pe față împotriva lor în discuții și combateri rostite și iarăși îndreptându-le părerile cu dovezi foarte exacte în lucrări scrise."},{"v":3,"t":"Și că Teofil a luptat și el, cu ceilalți, împotriva lor este vădit dintr-o anume cuvântare de nu obișnuit merit scrisă de el împotriva lui Marcion. Și această lucrare, ca și celelalte despre care am vorbit, a fost păstrată până în ziua de azi. Maximin, al șaptelea de la apostoli, i-a urmat ca episcop al bisericii din Antiohia."}];
window.LIB_LAZY["eusebiu-istoria#104"]=[{"v":1,"t":"Filip care, după cum aflăm din cuvintele lui Dionisie, a fost episcop al parohiei Gortinei, a scris de asemenea o lucrare foarte elaborată împotriva lui Marcion, la fel ca Irineu și Modest. Cel din urmă a dezvăluit rătăcirea omului mai limpede decât ceilalți înaintea tuturor. Mai sunt și alții, ale căror lucrări sunt încă prezentate de foarte mulți dintre frați."}];
window.LIB_LAZY["eusebiu-istoria#105"]=[{"v":1,"t":"În acele zile s-au bucurat de mare distincție și Melito, episcopul parohiei din Sardes, și Apolinarie, episcopul Hierapolei. Fiecare dintre ei, de partea lui, a adresat apologii în folosul credinței împăratului roman pomenit mai sus, care domnea în acel timp."},{"v":2,"t":"Următoarele lucrări ale acestor scriitori au ajuns la cunoștința noastră. Ale lui Melito: cele două cărți Despre Paște și una Despre purtarea vieții și proroci, cuvântarea Despre Biserică și una Despre ziua Domnului, mai departe una Despre credința omului și una Despre zidirea lui, alta de asemenea Despre ascultarea credinței și una Despre simțuri; pe lângă acestea, lucrarea Despre suflet și trup și cea Despre botez și cea Despre adevăr și Despre zidirea și nașterea lui Hristos; cuvântarea lui Despre proorocie și cea Despre ospitalitate; mai departe, Cheia și cărțile Despre diavol și Apocalipsa lui Ioan și lucrarea Despre corporalitatea lui Dumnezeu și, în sfârșit, cartea adresată lui Antonin."},{"v":3,"t":"În cărțile Despre Paște arată vremea în care a scris, începând cu aceste cuvinte: „Pe când Servilius Paulus era proconsul al Asiei, în vremea când Sagaris a suferit martiriul, s-a ridicat la Laodiceea o mare ceartă despre Paște, care cădea după rânduială în acele zile; și acestea au fost scrise.”"},{"v":4,"t":"Și Clement Alexandrinul se referă la această lucrare în propria lui cuvântare Despre Paște, pe care, spune el, a scris-o cu prilejul lucrării lui Melito."},{"v":5,"t":"Dar în cartea lui adresată împăratului însemnează că următoarele întâmplări ni s-au petrecut sub el: „Căci, ceea ce nu s-a mai întâmplat niciodată, neamul celor evlavioși suferă acum prigoană, fiind mânat prin Asia de noi decrete. Căci denunțătorii fără rușine și poftitorii averii altora, luând prilej din decrete, săvârșesc pe față tâlhărie noaptea și ziua, despuind pe cei vinovați de nicio nedreptate.” Și puțin mai departe spune: Dacă aceste lucruri se fac din porunca ta, bine și frumos. Căci un cârmuitor drept nu va lua niciodată măsuri nedrepte; și noi primim, într-adevăr, cu bucurie cinstea unei asemenea morți."},{"v":6,"t":"Dar numai această cerere o înfățișăm ție, ca tu însuți să cercetezi mai întâi pe autorii unei asemenea certe și să judeci drept dacă sunt vrednici de moarte și pedeapsă sau de siguranță și liniște. Dar dacă, pe de altă parte, acest sfat și acest decret nou, care nu se cuvine să fie executat nici măcar împotriva dușmanilor barbari, nu este de la tine, cu atât mai mult te rugăm să nu ne lași expuși unui asemenea jaf fără lege din partea gloatei."},{"v":7,"t":"Iarăși adaugă următoarele: Căci filozofia noastră a înflorit mai înainte între barbari; dar ridicându-se între neamurile de sub stăpânirea ta, în timpul marii domnii a strămoșului tău Augustus, a devenit pentru imperiul tău în chip deosebit o binecuvântare de bun augur. Căci din acel timp puterea romanilor a crescut în măreție și strălucire. Acestei puteri i-ai urmat tu, ca stăpân dorit, și așa vei continua cu fiul tău, dacă păzești filozofia care a crescut împreună cu imperiul și care a ajuns la ființă cu Augustus; acea filozofie pe care strămoșii tăi au cinstit-o împreună cu celelalte religii."},{"v":8,"t":"Și o dovadă foarte convingătoare că învățătura noastră a înflorit spre binele unui imperiu fericit început este aceasta — că nu s-a întâmplat niciun rău de la domnia lui Augustus, ci, dimpotrivă, toate lucrurile au fost strălucite și slăvite, potrivit rugăciunilor tuturor."},{"v":9,"t":"Numai Nero și Domițian, înduplecați de unii calomniatori, au voit să defaime învățătura noastră și de la ei s-a întâmplat că minciuna a fost transmisă, în urma unei practici nerezonabile care stăpânește, de a aduce învinuiri clevetitoare împotriva creștinilor."},{"v":10,"t":"Dar părinții tăi evlavioși le-au îndreptat neștiința, mustrând adesea în scris pe mulți care cutezau să încerce măsuri noi împotriva lor. Printre ei, bunicul tău Adrian pare să fi scris multora și, de asemenea, lui Fundan, proconsulul și guvernatorul Asiei. Și tatăl tău, când și tu domneai cu el, a scris cetăților, oprindu-le să ia măsuri noi împotriva noastră; printre celelalte, larisenilor, tesalonicenilor, atenienilor și tuturor grecilor."},{"v":11,"t":"Și cât despre tine — de vreme ce părerile tale despre creștini sunt aceleași ca ale lor și, într-adevăr, mult mai binevoitoare și filozofice — suntem cu atât mai încredințați că vei face tot ce îți cerem. Aceste cuvinte se găsesc în lucrarea pomenită mai sus."},{"v":12,"t":"Dar în Extrasele făcute de el, același scriitor dă la începutul introducerii un catalog al cărților recunoscute ale Vechiului Testament, pe care este necesar să-l citez în acest loc. Scrie astfel:"},{"v":13,"t":"Melito către fratele său Onisim, salutare: De vreme ce ai exprimat adesea, în râvna ta pentru cuvânt, dorința să ai extrase făcute din Lege și din Proroci despre Mântuitorul și despre toată credința noastră și ai dorit și o înșirare exactă a cărților vechi, cu privire la numărul și rânduiala lor, m-am silit să îndeplinesc lucrarea, cunoscând râvna ta pentru credință și dorința ta de a căpăta înștiințare despre cuvânt și știind că tu, în dorul tău după Dumnezeu, prețuiești aceste lucruri mai presus de orice, luptându-te să dobândești mântuirea veșnică."},{"v":14,"t":"De aceea, când am mers spre răsărit și am ajuns la locul unde s-au vestit și s-au făcut aceste lucruri, am aflat cu exactitate cărțile Vechiului Testament și ți le trimit după cum sunt scrise mai jos. Numele lor sunt următoarele: Ale lui Moise, cinci cărți: Geneza, Exodul, Numerii, Leviticul, Deuteronomul; Iisus Navi, Judecători, Rut; ale Regilor, patru cărți; ale Cronicilor, două; Psalmii lui David, Pildele lui Solomon, Înțelepciunea de asemenea, Ecclesiastul, Cântarea Cântărilor, Iov; ale Proorocilor, Isaia, Ieremia; ale celor doisprezece proroci, o carte; Daniel, Ezechiel, Ezdra. Din care am făcut și extrasele, împărțindu-le în șase cărți. Acestea sunt cuvintele lui Melito."}];
window.LIB_LAZY["eusebiu-istoria#106"]=[{"v":1,"t":"O seamă de lucrări ale lui Apolinarie au fost păstrate de mulți și următoarele au ajuns la noi: Cuvântarea adresată pomenitului împărat, cinci cărți Împotriva grecilor, Despre adevăr, o carte întâi și a doua, și cele pe care le-a scris după aceea împotriva ereziei frigienilor, care nu mult după aceea a ieșit cu înnoirile ei, dar era atunci, ca să zic așa, la început, deoarece Montan, cu proorocițele lui mincinoase, punea atunci temeliile rătăcirii lui."}];
window.LIB_LAZY["eusebiu-istoria#107"]=[{"v":1,"t":"Și cât despre Musan, pe care l-am pomenit printre scriitorii de mai sus, există o anume cuvântare foarte aleasă, scrisă de el împotriva unor frați care trecuseră la erezia așa-numiților encratiți, care se ivise de curând și care introducea o rătăcire ciudată și vătămătoare. Se spune că Tațian a fost autorul acestei învățături mincinoase."}];
window.LIB_LAZY["eusebiu-istoria#108"]=[{"v":1,"t":"El este cel ale cărui cuvinte le-am citat puțin mai sus în privința acelui preaminunat om, Iustin, și despre care am spus că a fost ucenic al martirului. Irineu declară aceasta în cartea întâi a lucrării sale Împotriva ereziilor, unde scrie astfel despre el și despre erezia lui:"},{"v":2,"t":"Cei care se numesc encratiți și care au ieșit din Saturnin și Marcion au propovăduit celibatul, lepădând rânduiala dintâi a lui Dumnezeu și învinuind tacit pe Cel care a făcut parte bărbătească și parte femeiască pentru înmulțirea neamului omenesc. Au introdus și înfrânarea de la lucrurile numite de ei însuflețite, arătând astfel nerecunoștință față de Dumnezeul care a făcut toate lucrurile. Și tăgăduiesc mântuirea celui dintâi om."},{"v":3,"t":"Dar aceasta a fost descoperită de ei abia de curând, un anume Tațian fiind cel dintâi care a introdus această hulă. El a fost ascultător al lui Iustin și nu a exprimat nicio asemenea părere cât a fost cu el, dar după martiriul acestuia a părăsit Biserica și, înălțându-se cu gândul de a fi învățător și umflându-se cu ideea că este superior altora, a întemeiat un fel deosebit de învățătură a lui, născocind anumiți eoni nevăzuți ca urmașii lui Valentin, în timp ce, ca Marcion și Saturnin, a declarat căsătoria stricăciune și desfrânare. Argumentul lui împotriva mântuirii lui Adam, totuși, l-a născocit el însuși. Irineu scria astfel în acel timp."},{"v":4,"t":"Dar puțin mai târziu un anume om numit Sever a dat noi puteri pomenitei erezii și a făcut astfel ca cei care își luau obârșia din ea să fie numiți, după el, severieni."},{"v":5,"t":"Ei se slujesc, într-adevăr, de Lege, de Proroci și de Evanghelii, dar tâlcuiesc în felul lor spusele Sfintelor Scripturi. Și batjocoresc pe apostolul Pavel și resping epistolele lui și nu primesc nici măcar Faptele Apostolilor."},{"v":6,"t":"Dar întemeietorul lor dintâi, Tațian, a alcătuit o anumită combinație și culegere a Evangheliilor, nu știu cum, căreia i-a dat titlul Diatessaron și care este încă în mâinile unora. Dar se spune că a cutezat să parafrazeze unele cuvinte ale apostolului, ca să le îmbunătățească stilul."},{"v":7,"t":"A lăsat multe scrieri. Dintre acestea, cea mai folosită de multe persoane este vestita lui Cuvântare către greci, care pare și cea mai bună și mai folositoare dintre toate lucrările lui. În ea se ocupă de cele mai vechi timpuri și arată că Moise și proorocii evrei erau mai vechi decât toți oamenii vestiți dintre greci. Atât despre acești oameni."}];
window.LIB_LAZY["eusebiu-istoria#109"]=[{"v":1,"t":"În aceeași domnie, pe când ereziile abundau în regiunea dintre râuri, un anume Bardesan, un om foarte capabil și un foarte iscusit discutant în limba siriacă, după ce a alcătuit dialoguri împotriva urmașilor lui Marcion și împotriva unor alții care erau autori ai unor păreri felurite, le-a pus în scris în limba lui, împreună cu multe alte lucrări. Elevii lui, dintre care avea foarte mulți (căci era un puternic apărător al credinței), au tradus aceste lucrări din siriacă în greacă."},{"v":2,"t":"Printre ele este și dialogul lui foarte capabil Despre soartă, adresat lui Antonin, și alte lucrări pe care se spune că le-a scris cu prilejul prigoanei care s-a ridicat în acel timp."},{"v":3,"t":"El a fost într-adevăr la început un urmaș al lui Valentin, dar după aceea, lepădându-i învățătura și combătând cea mai mare parte din născocirile lui, și-a închipuit că a trecut la părerea mai corectă. Totuși nu a spălat cu totul murdăria vechii erezii. Cam în acest timp a părăsit această viață și Soter, episcopul Bisericii din Roma."}];
